def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to remove build metadata
        v_without_build = v.split('+')[0]

        # Split on '-' to separate version from pre-release
        if '-' in v_without_build:
            version_part, prerelease_part = v_without_build.split('-', 1)
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part is not None:
            identifiers = prerelease_part.split('.')
            prerelease_tuple = tuple(
                (0, int(ident)) if ident.isdigit() else (1, ident)
                for ident in identifiers
            )
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(item):
        idx, version = item
        major, minor, patch, prerelease_tuple = parse_version(version)

        # Versions with pre-release sort before those without
        if prerelease_tuple is None:
            prerelease_sort_key = (1,)  # No pre-release
        else:
            prerelease_sort_key = (0, prerelease_tuple)  # Has pre-release

        return (major, minor, patch, prerelease_sort_key, idx)

    indexed_versions = [(i, v) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

